<?php
namespace App\Core;
final class AdminTheme
{
    public static function blend(string $a,string $b,float $ratio): string { $a=sscanf($a,'#%02x%02x%02x'); $b=sscanf($b,'#%02x%02x%02x'); return sprintf('#%02x%02x%02x',...array_map(static fn($x,$y)=>(int)round($x*(1-$ratio)+$y*$ratio),$a,$b)); }
    public static function contrast(string $hex): string { $rgb=sscanf($hex,'#%02x%02x%02x'); $v=array_map(static function($n){$n/=255; return $n<=.04045?$n/12.92:(($n+.055)/1.055)**2.4;},$rgb); return (.2126*$v[0]+.7152*$v[1]+.0722*$v[2])>.179?'#101317':'#f4f7f0'; }
    public static function head(): string { $p=ThemeService::profile(); $bg=$p['bg_color']; $text=self::contrast($bg); $light=$text==='#101317'; $panel=self::blend($bg,$light?'#000000':'#ffffff',.055); $border=self::blend($bg,$light?'#000000':'#ffffff',.22); return '<style id="goldensite-admin-theme" data-admin-theme="'.ConsoleView::escape(ThemeService::active()).'">:root{--nx-admin-bg:'.$bg.';--nx-admin-panel:'.$panel.';--nx-admin-field:'.self::blend($bg,$light?'#ffffff':'#000000',.12).';--nx-admin-border:'.$border.';--nx-admin-accent:'.$p['primary_color'].';--nx-admin-accent-ink:'.self::contrast($p['primary_color']).';--nx-admin-text:'.$text.';--nx-admin-muted:'.self::blend($bg,$text,.68).'}</style><link rel="stylesheet" href="/assets/admin/theme-bridge.css?v=20261105">'; }
    public static function adapt(string $html): string {
        // Convert legacy inline declarations, not user text, source editors or status colors.
        return preg_replace_callback('/\bstyle=(["\x27])(.*?)\1/is',static function($m){ $style=$m[2]; $style=preg_replace('/\bbackground\s*:\s*(?:linear|radial)-gradient\([^;]+/i','background:var(--nx-admin-panel)',$style); $style=preg_replace('/\bbackground(?:-color)?\s*:\s*(?:#1e293b|#0f172a|#111827|#020617)\b/i','background:var(--nx-admin-panel)',$style); $style=preg_replace('/\bbackground(?:-color)?\s*:\s*(?:#38bdf8|#a855f7|#0ea5e9|#f59e0b|#6366f1)\b/i','background:var(--nx-admin-accent)',$style); $style=preg_replace('/(?<![a-z-])color\s*:\s*(?:#38bdf8|#a855f7|#0ea5e9|#f59e0b|#6366f1)\b/i','color:var(--nx-admin-accent)',$style); $style=preg_replace('/(?<![a-z-])color\s*:\s*(?:#fff(?:fff)?|#f8fafc|#e2e8f0)\b/i','color:var(--nx-admin-text)',$style); $style=preg_replace('/(?<![a-z-])color\s*:\s*(?:#94a3b8|#cbd5e1|#64748b)\b/i','color:var(--nx-admin-muted)',$style); $style=str_ireplace('#334155','var(--nx-admin-border)',$style); $style=preg_replace_callback('/font-family\s*:\s*([^;]+)/i',static fn($f)=>preg_match('/monospace|Consolas|Courier/i',$f[1])?$f[0]:'font-family:var(--nx-font,system-ui)',$style); return 'style='.$m[1].$style.$m[1]; },$html);
    }
}
